import{_ as p}from"./chunks/image-002.Dp2-bnLm.js";import{_ as t,o as e,c as o,a3 as _}from"./chunks/framework.DdpBa4_E.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/yan-tie-lun/16-刺复第十.md","filePath":"books/yan-tie-lun/16-刺复第十.md","lastUpdated":1794316978000}'),n={name:"books/yan-tie-lun/16-刺复第十.md"};function s(r,a,l,i,c,d){return e(),o("div",null,[...a[0]||(a[0]=[_('<p>刺复第十 【题解】</p><p>大夫本来希望从文学、贤良之处得到舆论上的支持和兴利妙计，但却受到文学、贤良的严厉批评，为此他深感失望，于是反过来批评文学、贤良装饰外表，冒充贤能，扰乱现实政治。对此，文学予以回复反击。文学尖锐地指出，当世在位的公卿，既不能像燕昭王那样礼贤下士，也不能像《鹿鸣》那样娱乐贤才，反而像臧文仲、子椒一样嫉贤妒能，以自己高官厚禄蔑视贤才，因而不可能求得贤士为其所用。</p><p>大夫曰为色矜而心不怿[(1)]，曰：“但居者不知负载之劳[(2)]，从旁议者与当局者异忧[(3)]。方今为天下腹居郡[(4)]，诸侯并臻[(5)]，中外未然[(6)]，心憧憧若涉大川[(7)]，遭风而未薄[(8)]。是以夙夜思念国家之用，寝而忘寐，饥而忘食，计数不离于前[(9)]，万事简阅于心[(10)]。丞史器小[(11)]，不足与谋，独郁大道[(12)]，思睹文学，若俟周、邵而望高子[(13)]。御史案事郡国[(14)]，察廉举贤才，岁不乏也。今贤良、文学臻者六十余人[(15)]，怀六艺之术，骋意极论[(16)]，宜若开光发蒙[(17)]；信往而乖于今[(18)]，道古而不合于世务。意者不足以知士也[(19)]？将多饰文诬能以乱实邪[(20)]？何贤士之难睹也！自千乘倪宽以治《尚书》位冠九卿[(21)]，及所闻睹选举之士[(22)]，擢升赞宪甚显[(23)]，然未见绝伦比[(24)]，而为县官兴滞立功也[(25)]。”</p><p>【注释】</p><p>[(1)]曰：通“爰”，于是。色矜：面色矜持、严肃。怿（yì）：愉快。</p><p>[(2)]但居者：赋闲在家的人。但，徒，空。</p><p>[(3)]当局：当政。异忧：忧愁的内容不一样。</p><p>[(4)]腹居郡：指京师。腹居，中心。</p><p>[(5)]并臻：汇集，聚集。</p><p>[(6)]中：内地。外：边境。未然：没有安定。</p><p>[(7)]憧憧（chōnɡ）：心神不安貌。</p><p>[(8)]薄：通“泊”，指船靠岸。</p><p>[(9)]计数：各种计算数字。</p><p>[(10)]简阅：检查挑选，心中盘算。</p><p>[(11)]丞史：丞相史和御史。器小：指见识浅薄。</p><p>[(12)]独郁大道：独自忧郁，找不到治国大道。</p><p>[(13)]俟：等待。周：周公。邵：一作“召”，邵公，周文王庶子，名奭。周、召二公同心辅佐年幼的周成王，是西周初年两位最重要的政治家。高子：原作“子高”，据陈遵默说校改。高子，春秋时期齐国上卿，曾奉齐桓公之命，立僖公为鲁君。</p><p>[(14)]案事：考察事务。</p><p>[(15)]臻：至，到。</p><p>[(16)]骋意：尽情发表意见。极论：尽量展开议论。</p><p>[(17)]开光：开拓闪光的境界。发蒙：启发蒙昧。</p><p>[(18)]信往：相信古代。乖于今：不符合当今需要。</p><p>[(19)]意者：料想，看来。</p><p>[(20)]饰文：装饰外表。诬能：冒充贤能。</p><p>[(21)]倪宽：西汉千乘（今山东广饶）人，治《尚书》，汉武帝时任御史大夫。九卿：西汉以太常、光禄勋、卫尉、太仆、廷尉、大鸿胪、宗正、大司农、少府为九卿。倪宽为三公之一，位在九卿之上，故曰位冠九卿。</p><p>[(22)]闻睹：耳闻目睹。选举之士：指文学、贤良。</p><p>[(23)]擢升：提拔。赞宪：参与政事。甚显：十分显达。</p><p>[(24)]绝伦比：出类拔萃。</p><p>[(25)]兴滞：兴利除弊。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫于是脸色严肃而心中不快，说：“赋闲在家的人不知道背负肩挑人的劳苦，站在旁边议论的人与当政者有着不同的忧愁。当今处于天下中心的京师，诸侯都聚集到这里，内地和边境都没有安定，我的心中惶惶不安，如同乘船渡过大河，遭到风雨而未到岸。所以日夜思念国家的用度，躺在床上睡不着，肚子饿了忘记吃饭，各种统计数字萦绕在心头，成千上万的事情在心中掂量。丞相史见识短浅，不值得与他们谋划，独自郁闷找不到治国大道，我想着早一点见到你们文学，如同等待周公、邵公和盼望高子一样。御史到各处郡国考察，选拔孝廉，举荐贤才，每年都有不少。如今贤良、文学六十多人到来，带着《诗》、《书》、《礼》、《乐》、《易》、《春秋》的学术思想，尽情发表意见，纵论天下大事，应该能够发表闪光的思想，启发我的蒙昧；可是你们只相信古代，言论不符合当今需要，称道古人而不合当世之务。看来究竟是我们不足以知道高士？还是你们装饰外表、冒充贤能以扰乱现实呢？贤士为什么这么难以看到呢！自从千乘人倪宽因为治《尚书》而位在九卿之上，到今天耳闻目睹你们这些被选拔举荐的文学、贤良，提拔儒生参与政事，地位十分显达，然而没有看到出类拔萃的人，能够为朝廷兴利除弊建立功业。”</p><p>文学曰：“输子之制材木也[(1)]，正其规矩而凿枘调[(2)]。师旷之谐五音也[(3)]，正其六律而宫商调[(4)]。当世之工匠，不能调其凿枘，则改规矩，不能协声音，则变旧律。是以凿枘剌戾而不合[(5)]，声音泛越而不和[(6)]。夫举规矩而知宜[(7)]，吹律而知变[(8)]，上也；因循而不作，以俟其人，次也。是以曹丞相日饮醇酒[(9)]，倪大夫闭口不言[(10)]。故治大者不可以烦[(11)]，烦则乱；治小者不可以怠[(12)]，怠则废。《春秋》曰：‘其政恢卓，恢卓可以为卿相。其政察察，察察可以为匹夫。’[(13)]夫维纲不张[(14)]，礼义不行，公卿之忧也。案上之文[(15)]，期会之事[(16)]，丞史之任也。《尚书》曰：‘俊乂在官，百僚师师，百工惟时，庶尹允谐。’[(17)]言官得其人，人任其事，故官治而不乱，事起而不废，士守其职，大夫理其位，公卿总要执凡而已[(18)]。故任能者责成而不劳，任己者事废而无功。桓公之于管仲，耳而目之[(19)]。故君子劳于求贤，逸于用之，岂云殆哉[(20)]？昔周公之相也，谦卑而不邻[(21)]，以劳天下之士，是以俊乂满朝，贤智充门。孔子无爵位，以布衣从才士七十有余人，皆诸侯卿相之人也，况处三公之尊以养天下之士哉？今以公卿之上位，爵禄之美，而不能致士，则未有进贤之道。尧之举舜也，宾而妻之[(22)]。桓公举管仲也，宾而师之。以天子而妻匹夫，可谓亲贤矣。以诸侯而师匹夫[(23)]，可谓敬宾矣。是以贤者从之若流，归之不疑。今当世在位者，既无燕昭之下士[(24)]，《鹿鸣》之乐贤[(25)]，而行臧文、子椒之意[(26)]，蔽贤妒能，自高其智，訾人之才[(27)]，足己而不问，卑士而不友，以位尚贤[(28)]，以禄骄士，而求士之用，亦难矣！”</p><p>【注释】</p><p>[(1)]输子：公输子，即鲁班。制材木：制作木材。</p><p>[(2)]规：圆规。矩：曲尺。凿：榫眼。枘：榫头。调：准确配合。</p><p>[(3)]师旷：春秋时期晋国著名乐师。谐：调和。五音：古代音乐的五个音阶，即宫、商、角、徵、羽。</p><p>[(4)]六律：古代音乐十二律中的阳律，即黄钟、太簇、姑洗、蕤宾、夷则、亡射。</p><p>[(5)]剌戾：乖谬，形容榫头与榫眼不相符合。</p><p>[(6)]泛越：不合拍。</p><p>[(7)]宜：榫头与榫眼适宜。</p><p>[(8)]吹律：吹奏定音的调子。</p><p>[(9)]曹丞相日饮醇酒：《史记·曹相国世家》载：“参代何为汉相国，举事无所变更，一遵萧何约束……日夜饮醇酒。卿大夫已下吏及宾客见参不事事，来者皆欲有言。至者，参辄饮以醇酒，间之，欲有所言，复饮之，醉而后去，终莫得开说，以为常。”曹丞相，曹参。</p><p>[(10)]倪大夫：倪宽。《汉书·倪宽传》：“宽为御史大夫，以称意任职，故久无有所匡谏于上。”</p><p>[(11)]烦：烦杂。</p><p>[(12)]治小者不可以怠：“可”下原脱“以”字，据郭沫若说校补。</p><p>[(13)]其政恢卓，恢卓可以为卿相。其政察察，察察可以为匹夫：不见于今本《春秋》及其传记。陆贾《新语·辅政》：“察察者有所不见，恢恢者何所不容。”与文学所引《春秋》之语略近。恢卓，宽广。察察，严苛。</p><p>[(14)]维纲：渔网上的粗绳，此处指政治纲领。</p><p>[(15)]案上之文：案上的公文。</p><p>[(16)]期会之事：定期上报的事务。</p><p>[(17)]俊乂（yì）在官，百僚师师，百工惟时，庶尹允谐：见于《尚书·皋陶谟》，但“庶尹允谐”一句在后半部分。俊乂，贤才。师师，效法，向他学习。百工，百官。惟时，按时完成任务。庶尹，众位官长。允谐，和谐。</p><p>[(18)]总要：掌握要领。执凡：执掌大略。</p><p>[(19)]耳而目之：亲自听到，亲眼看到。</p><p>[(20)]殆：通“怠”，怠惰。</p><p>[(21)]邻：通“吝”。</p><p>[(22)]宾：以贵宾相待。妻之：把女儿嫁给他。《尚书·尧典》：“女于时，观其刑于二女。厘降二女于妫汭，嫔于虞。”</p><p>[(23)]而：原作“之”，据王利器说校改。</p><p>[(24)]燕昭之下士：《史记·燕召公世家》：“燕昭王于破燕之后即位，卑身厚币以招贤者……乐毅自魏往，邹衍自齐往，剧辛自赵往，士争趋燕。”</p><p>[(25)]《鹿鸣》之乐贤：《鹿鸣》是《诗经·小雅》中的一首诗。《毛诗序》说：“《鹿鸣》，燕群臣嘉宾也。既饮食之，又实币帛筐篚，以将其厚意，然后忠臣嘉宾得尽其心矣。”乐贤，娱乐贤才。</p><p>[(26)]臧文：臧文仲，春秋时期鲁国执政大夫。孔子曾经批评臧文仲不举荐贤士柳下惠，《论语·卫灵公》：“子曰：‘臧文仲其窃位者与！知柳下惠之贤，而不与立也。’”子椒：原作“子叔”，据王利器说校改。《离骚》中有“椒专佞以慢慆兮”、“览椒兰其若兹兮”的诗句，汉人遂以为诗中的“椒”名子椒，与子兰一起陷害屈原。</p><p>[(27)]訾（zī）：诋毁，诽谤。</p><p>[(28)]尚：同“上”。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“鲁班制作木材时，端正圆规和曲尺，使榫眼和榫头准确配合。师旷调和宫、商、角、徵、羽五个音调，准确地弹奏出黄钟、太簇、姑洗、蕤宾、夷则、亡射六个阳律而曲调和谐。当代的工匠，不能使榫眼与榫头准确配合，于是就修改圆规和曲尺；乐师不能协调乐曲声音，于是就改变旧的音律。所以榫眼和榫头乖谬而不相符，声音不合拍不和谐。举起圆规曲尺就知道该怎么合适，吹奏定音的调子就知道音乐节奏的变化，这是上等水平；因循守旧而不创新，等待合适的人，这是次一等水平。所以曹参当丞相时每日饮醇酒，倪宽大夫闭口不说话。因此治理任务重大的人不可以烦琐，烦琐就会导致混乱；治理任务小的人不可以懈怠，懈怠就会荒废工作。《春秋》说：‘执政气魄宏大，宏大可以担任卿相。执政严厉苛刻，苛刻只可以当老百姓。’执政纲领不明确，礼义不实行，这是公卿应该担忧的大事。案上的公文，定期上报的事务，这是丞相史的责任。《尚书·皋陶谟》说：‘贤才当官，同僚向他学习，百官按时完成任务，诸位官员都和谐。’说的是官府得到合适的人选，人人胜任自己的工作，因此官府得到治理而不紊乱，事业兴旺而不荒废，士人遵守各自的职责，大夫治理分内的工作，公卿总理大事、掌握大略而已。因此任用贤能的人，责其完成任务，自己不会劳苦；只信任自己的人导致事业荒废，没有功效。齐桓公对于管仲，只是耳听他说，眼看他做。因而君子在求贤时辛劳，在任用贤人后一劳永逸，怎么能说是懈怠呢？从前周公当宰相，谦卑而不吝啬，慰劳天下的贤士，所以贤才满朝，贤智满门。孔子没有爵位，他以布衣身份，让七十多个才士跟随他，这些人的才能都可以担任诸侯的卿相，何况处于朝廷三公的尊位来培养天下贤士呢？如今凭着公卿的上等职位，美好的爵位和俸禄，却不能招致贤士，那就说明缺少进贤的措施。唐尧推举虞舜，尊为上宾，将女儿嫁给他。齐桓公举荐管仲，尊为上宾，拜他为师。唐尧以天子之尊，将女儿嫁给平民，这可以说是亲近贤人了。齐桓公以诸侯之尊，拜平民为师，可以说敬重宾客了。所以贤才从之如流水，归附毫不迟疑。如今在位的公卿，既不能像燕昭王那样礼贤下士，像《诗经·小雅·鹿鸣》那样娱乐贤人，又亲身施行臧文仲、子椒的做法，嫉贤妒能，抬高自己的才智，诋毁他人的才能，自满自得，不肯向他人请教，轻视贤士，不愿与贤士做朋友，倚仗自己的地位，凌驾于贤人之上，以自己优厚的俸禄在贤士面前骄傲，却要求士人为己所用，这当然是很难的了！”</p><p>大夫缪然不言[(1)]，盖贤良长叹息焉[(2)]。</p><p>御史进曰：“太公相文、武以王天下，管仲相桓公以霸诸侯。故贤者得位，犹龙得水，腾蛇游雾也[(3)]。公孙丞相以《春秋》说先帝[(4)]，遽即三公[(5)]，处周、邵之列，据万里之势，为天下准绳[(6)]，衣不重彩[(7)]，食不兼味[(8)]，以先天下，而无益于治。博士褚泰、徐偃等[(9)]，承明诏[(10)]，建节驰传[(11)]，巡省郡国[(12)]，举孝廉[(13)]，劝元元[(14)]，而流俗不改。招举贤良、方正、文学之士[(15)]，超迁官爵，或至卿大夫，非燕昭之荐士，文王之广贤也？然而未睹功业所成。殆非龙蛇之才，而《鹿鸣》之所乐贤也。”</p><p>【注释】</p><p>[(1)]缪（mù）然：沉思貌。</p><p>[(2)]盖：发语词。</p><p>[(3)]腾蛇：龙类动物，据说能兴云驾雾。</p><p>[(4)]公孙丞相：公孙弘，汉淄川国薛县人，四十多岁开始学《春秋》杂说，六十多岁举文学，拜为博士，先后任汉朝御史大夫、丞相，封平津侯。</p><p>[(5)]遽即：立即，很快。</p><p>[(6)]准绳：本是木匠定平、取直的器具，引申为榜样，表率。</p><p>[(7)]重彩：两种颜色以上。</p><p>[(8)]兼味：多种味道。</p><p>[(9)]褚泰：春秋公羊学大师董仲舒弟子。初为梁相，通五经，为博士。徐偃：《鲁诗》大师申公弟子。公元前121年，徐偃与博士褚泰等六人奉诏分行郡国，慰问鳏寡废疾，无以自振业者，加以赈济。告谕三老、孝弟，成为民众之师。</p><p>[(10)]承明诏：奉皇帝英明的诏令。</p><p>[(11)]建节：树起使者符节。节，古代使者出外巡行所持的凭证。驰传：乘坐驿站的车辆。</p><p>[(12)]巡省：巡察。</p><p>[(13)]举孝廉：举荐孝廉。</p><p>[(14)]劝元元：鼓励老百姓。</p><p>[(15)]招举：征招举荐。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>大夫深思不说话，贤良长长地叹息。</p><p>御史上前说：“姜太公辅佐周文王、周武王称王天下，管仲辅佐齐桓公称霸诸侯。因此贤才得到官位，如同蛟龙得水，腾蛇兴云驾雾。公孙弘丞相向已故武帝讲述《春秋》，很快被提拔到三公地位，处于周公、邵公当年的位置，占据驾驭万里的势位，成为天下榜样，他不穿两种以上色彩的衣服，不吃多种味道的饭菜，为天下人做出表率，但对治国并没有多少益处。博士褚泰、徐偃等，承奉皇帝英明的诏令，树起使者符节，乘坐驿站的车辆，巡察各郡国，举荐孝廉，勉励老百姓，但流俗并没有为之改变。征招察举贤良、方正、文学之士，破格提拔官爵，有的人升为卿大夫，难道不是像燕昭王那样提拔贤士，像周文王那样广延贤才吗？然而没有看到这些人建立了什么功业。恐怕这些贤才并不是龙蛇之才，也不是《鹿鸣》诗中所娱乐的那些贤士吧。”</p><p>文学曰：“冰炭不同器[(1)]，日月不并明[(2)]。当公孙弘之时，人主方设谋垂意于四夷[(3)]，故权谲之谋进[(4)]，荆楚之士用[(5)]，将帅或至封侯食邑，而勊获者咸蒙厚赏[(6)]，是以奋击之士由此兴[(7)]。其后，干戈不休，军旅相望，甲士糜弊[(8)]，县官用不足，故设险兴利之臣起[(9)]，磻溪熊罴之士隐[(10)]。泾渭造渠以通漕运[(11)]，东郭咸阳、孔仅建盐铁[(12)]，策诸利[(13)]，富者买爵贩官，免刑除罪[(14)]，公用弥多而为者徇私[(15)]，上下兼求[(16)]，百姓不堪，抏弊而从法[(17)]，故憯急之臣进[(18)]，而见知、废格之法起[(19)]。杜周、咸宣之属[(20)]，以峻文决理贵[(21)]，而王温舒之徒以鹰隼击杀显[(22)]。其欲据仁义以道事君者寡，偷合取容者众[(23)]。独以一公孙弘，如之何？”</p><p>【注释】</p><p>[(1)]冰炭不同器：冰和炭不能放在同一个容器里，即水火不容。</p><p>[(2)]日月不并明：太阳月亮不会同时升起。</p><p>[(3)]垂意：留意。四夷：指四境之外的少数民族。</p><p>[(4)]权谲：权术诡诈。</p><p>[(5)]荆楚之士：能征善战的将士。楚人善战，故以荆楚之士指代勇士。</p><p>[(6)]勊获：杀敌有功。原作“勉获”，据孙诒让说校改。勊，同“克”。</p><p>[(7)]奋击之士：奋勇杀敌的勇士。</p><p>[(8)]糜弊：疲惫不堪。原作“麋弊”，据黄侃说校改。</p><p>[(9)]设险：设置险阻关卡。</p><p>[(10)]磻（pán）溪：溪名，在今陕西宝鸡东南，相传姜太公在此垂钓，遇到周文王。熊罴（pí）之士：喻勇武之士，指姜太公。</p><p>[(11)]渭：原作“淮”，据王利器说校改。《汉书·武帝纪》：“元光六年春，穿漕运渠通渭。”如淳曰：“水转运曰漕。”</p><p>[(12)]东郭咸阳：原作“东郭偃”，据张敦仁说校改。</p><p>[(13)]策诸利：策划各种兴利措施。</p><p>[(14)]买爵贩官，免刑除罪：汉代文、景时期，朝廷采用晁错建议，实行有钱的人可以用钱粮买官爵，有罪的人可以用钱粮赎罪的措施。汉武帝继续沿用这些政策。</p><p>[(15)]为者徇私：经管官员营私舞弊。</p><p>[(16)]兼：原作“无”，据张敦仁说校改。</p><p>[(17)]抏（wán）弊：通“抏敝”，消耗凋敝。</p><p>[(18)]憯急：刻薄严酷。憯，同“惨”，刻毒。急，急躁。</p><p>[(19)]见知：对知道案情而不检举的人治罪。废格：对不执行国家法令或执行不严的人治罪。</p><p>[(20)]杜周：汉南阳郡杜衍（今河南南阳西南）人。汉武帝时历任廷尉史、中丞、御史大夫。咸宣：即减宣，汉河东郡杨县（今山西洪洞东南）人。汉武帝时历任御史、中丞。二人均为西汉著名酷吏，事迹见《史记·酷吏列传》。</p><p>[(21)]峻文决理：以严峻的法律条文办理案件。</p><p>[(22)]王温舒：汉左冯翊阳陵（今陕西咸阳东）人。汉武帝时历任廷尉、都尉、太守等职。隼：一种凶猛的鸟。显：显贵。王温舒以狂捕滥杀闻名，事迹见《史记·酷吏列传》。</p><p>[(23)]偷合取容：犹言“苟合取容”，指阿谀奉承，讨上司的欢心。</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>【译文】</p><p>文学说：“冰和炭不能放在同一个容器，太阳和月亮不会同时大放光明。在公孙弘时代，君主正在设计谋略，留意外伐四夷，因此权术诡诈的谋略得到采纳，能征善战的将士得到重用，有的将帅封爵诸侯食用采邑，克敌俘获的将士都受到厚赏，所以奋勇杀敌的勇士由此兴起。后来，战争无休无止，军队相望于道路，披甲将士疲惫不堪，朝廷费用不足，因此设置险阻关卡、兴办财利之臣得到重用，像姜太公那样垂钓磻溪的韬略之士只好退隐。疏通泾水、渭水，开凿沟渠，以便打通水运通道，东郭咸阳、孔仅建议盐铁官营，策划各种兴利措施，有钱人购买官爵，用钱赎罪免刑，国家开支费用越来越多，经管官员营私舞弊，从上到下都谋求利益，老百姓痛苦不堪，消耗凋敝而又不得不服从法令，因此刻薄严酷官员得到进用，而关于知情不报、执法不力的法令出台。杜周、减宣之流，凭借严峻的法律条文办理案件的官员显贵，而王温舒之徒凭借狂捕滥杀显达。希望依据仁义、以正道事奉君主的人很少，阿谀奉承，讨上司欢心的人众多。只有一个公孙弘，又有什么办法呢？”</p>',115)])])}const y=t(n,[["render",s]]);export{g as __pageData,y as default};
